<?php
declare(strict_types=1);
require_once __DIR__ . '/conn.php';
$review=$_SESSION['sdk_registration_review']??null;
if(!is_array($review)){header('Location: login.php');exit;}
$remaining=max(0,(int)($review['ready_at']??time())-time());
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Account created</title><style>*{box-sizing:border-box}body{margin:0;min-height:100svh;display:grid;place-items:center;padding:20px;background:radial-gradient(circle at 20% 0,rgba(79,142,247,.16),transparent 34rem),#050810;color:#f8fafc;font-family:Inter,system-ui}.card{width:min(92vw,520px);padding:30px;border-radius:26px;background:rgba(15,23,42,.9);border:1px solid rgba(255,255,255,.11);box-shadow:0 30px 90px rgba(0,0,0,.45)}.row{display:flex;justify-content:space-between;gap:15px;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.07)}.row span{color:#94a3b8}button{width:100%;margin-top:22px;padding:14px;border:0;border-radius:13px;background:linear-gradient(135deg,#c9a84c,#4f8ef7);font-weight:900;color:#07111f}.muted{color:#94a3b8;line-height:1.55}</style></head><body><main class="card"><h1>Account created</h1><p class="muted">Review the safe account details below. Your password is never displayed. Login unlocks after the server-enforced 15-second review window.</p><div class="row"><span>Username</span><b><?=htmlspecialchars((string)$review['username'])?></b></div><div class="row"><span>Role</span><b><?=htmlspecialchars((string)$review['role'])?></b></div><div class="row"><span>Signup balance</span><b><?=(int)$review['balance']?></b></div><div class="row"><span>Referral</span><b><?=htmlspecialchars((string)$review['referral'])?></b></div><div class="row"><span>Created</span><b><?=htmlspecialchars(sdk_feature_display_time((string)$review['created_at']))?></b></div><button id="go" disabled>Continue in <span id="n"><?=$remaining?></span>s</button></main><script>(()=>{let n=<?=$remaining?>,b=document.getElementById('go'),s=document.getElementById('n');const t=setInterval(()=>{n=Math.max(0,n-1);s.textContent=n;if(n===0){clearInterval(t);b.disabled=false;b.textContent='Continue to login';b.onclick=()=>location.href='login.php?registered=1'}},